-- ==========================================
-- 1. PEMBUATAN STRUKTUR TABEL
-- ==========================================

CREATE TABLE IF NOT EXISTS Kamar (
    id_kamar VARCHAR(20) PRIMARY KEY,
    penasehat VARCHAR(100),
    ketua_kamar VARCHAR(100)
);

CREATE TABLE IF NOT EXISTS Santri (
    id_santri INTEGER PRIMARY KEY AUTOINCREMENT,
    id_kamar VARCHAR(20),
    nama_lengkap VARCHAR(100),
    nik VARCHAR(50),
    nama_ayah VARCHAR(100),
    no_telp_wali VARCHAR(50),
    alamat_lengkap TEXT,
    madrasah VARCHAR(10),
    kelas VARCHAR(50),
    lama_baru VARCHAR(10),
    FOREIGN KEY (id_kamar) REFERENCES Kamar(id_kamar)
);

